+    if (payload.replace) {
+        card._decoder = new LiveArgsDecoder();
+        if ((payload.chars || 0) > content.length) card._decoder.feedTail(content);
+        else card._decoder.feed(content);
+    } else if (content) {
+        card._decoder.feed(content);
